"""Unified browser-native EconAtlas management panel."""

PANEL_HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>EconAtlas · 全球宏观数据平台</title>
<style>
:root{--primary:#5868ef;--primary-soft:#eef1ff;--text:#172033;--muted:#7b879b;--line:#e3e8f1;--bg:#f5f7fb;--good:#16a77a;--warn:#e89b2c}*{box-sizing:border-box}body{margin:0;font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif;background:var(--bg);color:var(--text)}button,input,textarea{font:inherit}.top{height:64px;position:fixed;inset:0 0 auto 0;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 24px;z-index:20}.brand{display:flex;align-items:center;gap:11px;font-weight:800;font-size:21px;color:#263e71}.logo{width:34px;height:34px;border-radius:11px;background:linear-gradient(135deg,#4778ff,#7658ee);color:#fff;display:grid;place-items:center}.top-sub{margin-left:16px;padding-left:16px;border-left:1px solid var(--line);font-size:13px;color:var(--muted)}.top-status{margin-left:auto;display:flex;gap:9px}.pill{font-size:12px;border:1px solid var(--line);border-radius:20px;padding:7px 11px;color:#657189;background:#fff}.pill i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--good);margin-right:6px}.side{position:fixed;top:64px;bottom:0;left:0;width:246px;background:#fff;border-right:1px solid var(--line);padding:18px 13px;overflow:auto}.group{font-size:11px;color:#a0a9b9;margin:18px 13px 7px;letter-spacing:.08em}.menu{width:100%;border:0;background:transparent;text-align:left;padding:11px 13px;border-radius:8px;color:#556176;cursor:pointer;margin:2px 0}.menu:hover{background:#f5f7fc}.menu.active{background:var(--primary-soft);color:var(--primary);font-weight:700}.menu span{display:inline-block;width:25px}.main{margin-left:246px;padding-top:64px;min-height:100vh}.content{max-width:1480px;margin:auto;padding:28px}.page-head{display:flex;align-items:flex-start;margin-bottom:22px}.page-head h1{font-size:25px;margin:0 0 7px}.page-head p{margin:0;color:var(--muted);font-size:14px}.head-action{margin-left:auto}.btn{border:1px solid var(--line);background:#fff;border-radius:8px;padding:9px 14px;cursor:pointer;color:#526077}.btn.primary{background:var(--primary);border-color:var(--primary);color:#fff}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 4px 16px #24345208}.card{padding:18px}.card label{font-size:13px;color:var(--muted)}.card strong{display:block;font-size:26px;margin:10px 0 4px}.card small{color:#98a2b3}.grid2{display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-top:16px}.panel{padding:20px}.panel h3{font-size:16px;margin:0 0 15px}.bars{display:flex;flex-direction:column;gap:11px}.bar-row{display:grid;grid-template-columns:150px 1fr 70px;gap:10px;align-items:center;font-size:13px}.track{height:8px;background:#eef1f6;border-radius:5px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#6174f5,#7f66ee);border-radius:5px}.pipeline{display:grid;gap:11px}.step{border:1px solid var(--line);border-radius:9px;padding:12px}.step b{color:var(--primary)}.step small{display:block;color:var(--muted);margin-top:4px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px;background:#fff}table{width:100%;border-collapse:collapse;font-size:13px}th{position:sticky;top:0;background:#f8f9fc;text-align:left;color:#69758a;padding:12px;border-bottom:1px solid var(--line)}td{padding:11px 12px;border-bottom:1px solid #edf0f5;white-space:nowrap}.empty{padding:60px 20px;text-align:center;color:var(--muted)}.chat-layout{display:grid;grid-template-columns:230px 1fr;min-height:calc(100vh - 145px);background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}.chat-side{border-right:1px solid var(--line);padding:16px;background:#fbfcff}.new-chat{width:100%;border:1px solid #dbe1f1;background:var(--primary-soft);color:var(--primary);border-radius:8px;padding:11px;cursor:pointer}.chat-side input{width:100%;margin-top:12px;border:1px solid var(--line);border-radius:7px;padding:10px}.chat-main{position:relative;padding:20px 28px 125px;min-width:0}.chat-title{display:flex;align-items:center;padding-bottom:14px;border-bottom:1px solid var(--line)}.chat-title b{font-size:17px}.chat-title .pill{margin-left:auto}.hero{text-align:center;padding:100px 15px 35px}.hero-icon{width:52px;height:52px;margin:auto;border-radius:17px;background:linear-gradient(135deg,#526cf1,#8767ef);color:#fff;display:grid;place-items:center;font-size:24px}.hero h2{font-size:27px;margin:18px 0 8px}.hero p{color:var(--muted)}.chips{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.chips button{border:1px solid var(--line);background:#fff;border-radius:18px;padding:8px 13px;color:#657189;cursor:pointer}.messages{max-width:900px;margin:22px auto}.msg{display:flex;margin:18px 0}.bubble{max-width:82%;padding:13px 16px;border-radius:12px;line-height:1.72;white-space:pre-wrap}.user{justify-content:flex-end}.user .bubble{background:var(--primary);color:#fff}.bot .bubble{background:#f9faff;border:1px solid var(--line)}.evidence{font-size:12px;color:var(--muted);margin-top:10px}.composer{position:absolute;left:28px;right:28px;bottom:24px;border:1px solid #dbe1ec;background:#fff;border-radius:14px;padding:12px;box-shadow:0 12px 30px #22355d18}.composer textarea{border:0;outline:0;resize:none;width:100%;height:46px}.composer-foot{display:flex;align-items:center}.composer-foot .pill{color:var(--primary);background:var(--primary-soft)}.send{margin-left:auto}.status-text{font-size:12px;color:var(--muted);margin-left:9px}.badge{display:inline-block;padding:4px 8px;border-radius:12px;background:#eefaf6;color:var(--good);font-size:12px}.api-list{display:grid;gap:10px}.api{display:grid;grid-template-columns:65px 180px 1fr;gap:12px;padding:12px;border:1px solid var(--line);border-radius:8px}.method{font-weight:700;color:var(--primary)}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.top-status{display:none}}@media(max-width:760px){.side{display:none}.main{margin-left:0}.content{padding:18px}.cards{grid-template-columns:1fr}.chat-layout{grid-template-columns:1fr}.chat-side{display:none}.chat-main{padding:15px 15px 120px}.composer{left:15px;right:15px}.top-sub{display:none}}
</style></head><body>
<header class="top"><div class="brand"><div class="logo">◇</div>EconAtlas</div><div class="top-sub">全球宏观经济数据要素平台</div><div class="top-status"><span class="pill"><i></i>数据库在线</span><span class="pill"><i></i>API 正常</span><span class="pill" id="ai-status"><i></i>DeepSeek</span></div></header>
<aside class="side"><div class="group">工作台</div><button class="menu active" data-page="overview"><span>⌂</span>平台总览</button><div class="group">数据管理</div><button class="menu" data-page="assets"><span>▤</span>数据资产</button><button class="menu" data-page="indicators"><span>◫</span>指标中心</button><button class="menu" data-page="quality"><span>✓</span>数据质量</button><div class="group">治理分析</div><button class="menu" data-page="governance"><span>⌘</span>数据治理</button><button class="menu" data-page="risk"><span>△</span>风险预警</button><div class="group">智能服务</div><button class="menu" data-page="chat"><span>✦</span>智能问答</button><button class="menu" data-page="report"><span>▧</span>智能报告</button><div class="group">开放服务</div><button class="menu" data-page="api"><span>⌁</span>API 服务</button><button class="menu" data-page="system"><span>◉</span>系统运行</button></aside>
<main class="main"><div class="content" id="content"></div></main>
<script>
const content=document.getElementById('content');let summary=null,metadata=null,context=null,history=[];
const fmt=n=>new Intl.NumberFormat('zh-CN').format(Number(n||0));const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const md=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[E(\d+)\]/g,'<span class="pill">[E$1]</span>').replace(/\n/g,'<br>');
async function getData(){const [s,m]=await Promise.all([fetch('/dashboard-summary').then(r=>r.json()),fetch('/metadata').then(r=>r.json())]);summary=s;metadata=m;document.getElementById('ai-status').innerHTML='<i></i>'+(s.deepseek_configured?'DeepSeek 在线':'DeepSeek 未配置')}
function head(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function overview(){const t=summary?.totals||{},valid=t.rows?Math.round(t.valid_rows/t.rows*10000)/100:0;const sources=summary?.source_counts||[],max=Math.max(...sources.map(x=>x.rows),1);content.innerHTML=head('平台总览','查看数据资产规模、质量状态与系统运行情况','<div class="head-action"><button class="btn" onclick="loadPage(\'overview\')">刷新数据</button></div>')+`<div class="cards"><div class="card"><label>标准观测记录</label><strong>${fmt(t.rows)}</strong><small>${t.earliest_date||'-'} 至 ${t.latest_date||'-'}</small></div><div class="card"><label>国家与地区</label><strong>${fmt(t.countries)}</strong><small>统一国家编码</small></div><div class="card"><label>标准指标</label><strong>${fmt(t.indicators)}</strong><small>统一指标口径</small></div><div class="card"><label>官方数据来源</label><strong>${fmt(t.sources)}</strong><small>保留完整血缘</small></div><div class="card"><label>有效数据率</label><strong>${valid}%</strong><small>有效记录 ${fmt(t.valid_rows)}</small></div></div><div class="grid2"><section class="panel"><h3>数据来源分布</h3><div class="bars">${sources.slice(0,8).map(x=>`<div class="bar-row"><span>${esc(x.source)}</span><div class="track"><div class="fill" style="width:${x.rows/max*100}%"></div></div><b>${fmt(x.rows)}</b></div>`).join('')}</div></section><section class="panel"><h3>数据治理链路</h3><div class="pipeline"><div class="step"><b>01 多源采集</b><small>连接官方与权威宏观数据源</small></div><div class="step"><b>02 标准治理</b><small>统一国家、指标、频率和单位</small></div><div class="step"><b>03 质量校验</b><small>检查缺失、异常与多源一致性</small></div><div class="step"><b>04 智能服务</b><small>API、报告与 DeepSeek 数据问答</small></div></div></section></div>`}
async function assets(){content.innerHTML=head('数据资产','浏览已治理的国家—指标—来源数据资产')+'<div class="panel"><div class="empty">正在加载数据资产…</div></div>';const d=await fetch('/assets?limit=100').then(r=>r.json());content.innerHTML=head('数据资产','浏览已治理的国家—指标—来源数据资产',`<div class="head-action"><span class="badge">展示 ${d.count||0} 项</span></div>`)+`<div class="table-wrap"><table><thead><tr><th>国家/地区</th><th>指标</th><th>频率</th><th>来源</th><th>有效/总数</th><th>时间范围</th></tr></thead><tbody>${(d.assets||[]).map(x=>`<tr><td>${esc(x.country_name_zh||x.country_code)}</td><td>${esc(x.indicator_name_zh||x.indicator_code)}</td><td>${esc(x.frequency)}</td><td>${esc(x.source_organization)}</td><td>${fmt(x.valid_observations)} / ${fmt(x.observations)}</td><td>${esc(x.start_date)} — ${esc(x.end_date)}</td></tr>`).join('')}</tbody></table></div>`}
function indicators(){const list=metadata?.indicators||[];content.innerHTML=head('指标中心','统一管理标准指标编码、名称与数据口径')+`<div class="panel"><h3>标准指标目录 <span class="badge">${list.length} 项</span></h3><div class="chips" style="justify-content:flex-start">${list.map(x=>`<button>${esc(x)}</button>`).join('')}</div></div>`}
function quality(){const t=summary?.totals||{},missing=(t.rows||0)-(t.valid_rows||0),rate=t.rows?((t.valid_rows/t.rows)*100).toFixed(2):0;content.innerHTML=head('数据质量','检查数据完整性、预测值标识和来源覆盖')+`<div class="cards"><div class="card"><label>有效记录</label><strong>${fmt(t.valid_rows)}</strong><small>可直接用于查询</small></div><div class="card"><label>缺失观测</label><strong>${fmt(missing)}</strong><small>进入质量审查</small></div><div class="card"><label>完整率</label><strong>${rate}%</strong><small>全库字段统计</small></div><div class="card"><label>预测记录</label><strong>${fmt(t.forecasts)}</strong><small>与历史值明确区分</small></div><div class="card"><label>来源覆盖</label><strong>${fmt(t.sources)}</strong><small>支持来源追溯</small></div></div><div class="panel" style="margin-top:16px"><h3>质量控制原则</h3><div class="pipeline"><div class="step"><b>完整性</b><small>空值、断点与时间覆盖检查</small></div><div class="step"><b>一致性</b><small>指标单位、频率与多源偏差检查</small></div><div class="step"><b>可追溯性</b><small>保留来源机构、数据集、原始代码和 URL</small></div></div></div>`}
function governance(){content.innerHTML=head('数据治理','展示从来源数据到标准资产的治理过程')+`<div class="grid2"><section class="panel"><h3>治理规则</h3><div class="pipeline"><div class="step"><b>指标映射</b><small>来源指标映射至 EconAtlas 标准编码</small></div><div class="step"><b>频率与单位统一</b><small>规范年度、季度、月度与日度口径</small></div><div class="step"><b>数据语义标注</b><small>区分 historical、forecast 与 derived</small></div><div class="step"><b>质量门禁</b><small>自动更新必须通过完整性与语义检查</small></div></div></section><section class="panel"><h3>治理成果</h3><p>当前标准库覆盖 <b>${fmt(summary?.totals?.countries)}</b> 个国家与地区、<b>${fmt(summary?.totals?.indicators)}</b> 个标准指标，并保留完整数据来源。</p></section></div>`}
function generic(title,desc,body){content.innerHTML=head(title,desc)+`<div class="panel">${body}</div>`}
function apiPage(){content.innerHTML=head('API 服务','通过标准 HTTP 接口开放数据资产与智能能力')+`<div class="panel"><div class="api-list"><div class="api"><span class="method">GET</span><code>/health</code><span>服务健康检查</span></div><div class="api"><span class="method">GET</span><code>/metadata</code><span>数据资产元数据</span></div><div class="api"><span class="method">GET</span><code>/query</code><span>单指标时间序列查询</span></div><div class="api"><span class="method">POST</span><code>/batch_query</code><span>批量数据查询</span></div><div class="api"><span class="method">POST</span><code>/chat</code><span>DeepSeek + EconAtlas 智能问答</span></div></div></div>`}
function chat(){content.innerHTML=head('智能问答','DeepSeek 通用对话 · EconAtlas 宏观数据增强')+`<div class="chat-layout"><aside class="chat-side"><button class="new-chat" onclick="resetChat()">＋ 新建对话</button><input placeholder="搜索会话标题"><div class="group">最近 30 天</div><div style="padding:10px;color:#59657a">当前对话</div></aside><section class="chat-main"><div class="chat-title"><b>智能问答</b><span class="pill"><i></i>DeepSeek 在线 · 数据检索可用</span></div><div class="hero" id="hero"><div class="hero-icon">✦</div><h2>EconAtlas 智能问答</h2><p>普通问题由 DeepSeek 回答，宏观数据问题自动检索 EconAtlas</p><div class="chips"><button onclick="ask(this.textContent)">你好，你能做什么？</button><button onclick="ask(this.textContent)">解释一下什么是 GDP</button><button onclick="ask(this.textContent)">中国近五年的通胀趋势</button></div></div><div class="messages" id="messages"></div><div class="composer"><textarea id="question" placeholder="直接提问；Enter 发送，Shift+Enter 换行"></textarea><div class="composer-foot"><span class="pill">DeepSeek · EconAtlas 数据增强</span><span class="status-text" id="chat-status"></span><button class="btn primary send" id="send" onclick="submitQuestion()">发送 ➤</button></div></div></section></div>`;const q=document.getElementById('question');q.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submitQuestion()}})}
function addMessage(role,text,evidence=[]){document.getElementById('hero').style.display='none';const el=document.createElement('div');el.className='msg '+role;const b=document.createElement('div');b.className='bubble';b.innerHTML=md(text);if(evidence.length){const x=document.createElement('div');x.className='evidence';x.textContent='数据证据：'+evidence.length+' 条 · 来源：'+[...new Set(evidence.map(v=>v.source_organization).filter(Boolean))].join('、');b.appendChild(x)}el.appendChild(b);document.getElementById('messages').appendChild(el);el.scrollIntoView({behavior:'smooth',block:'end'})}
function ask(t){document.getElementById('question').value=t;submitQuestion()}async function submitQuestion(){const q=document.getElementById('question'),send=document.getElementById('send'),status=document.getElementById('chat-status'),text=q.value.trim();if(!text||send.disabled)return;const prior=history.slice(-20);addMessage('user',text);history.push({role:'user',content:text});q.value='';send.disabled=true;status.textContent='DeepSeek 正在理解问题…';try{const r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:text,context,history:prior})});const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'请求失败');context=d.context;addMessage('bot',d.answer,d.evidence||[]);history.push({role:'assistant',content:d.answer})}catch(e){addMessage('bot','暂时无法生成回答：'+e.message)}finally{send.disabled=false;status.textContent=''}}function resetChat(){context=null;history=[];chat()}
async function loadPage(page){document.querySelectorAll('.menu').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(!summary)await getData();({overview,assets,indicators,quality,governance,chat,api:apiPage,system:()=>generic('系统运行','查看云端服务与自动化运行状态',`<h3>云端服务正常</h3><p><span class="badge">数据库在线</span>　<span class="badge">API 正常</span>　<span class="badge">DeepSeek ${summary.deepseek_configured?'已配置':'未配置'}</span></p><p>当前采用 FastAPI + Uvicorn 提供 HTTP 服务，避免依赖本地电脑运行。</p>`),risk:()=>generic('风险预警','集中展示数据质量与多源偏差风险','<h3>风险监测</h3><p>当前风险模块基于缺失值、异常观测、来源冲突和更新时效生成预警。</p>'),report:()=>generic('智能报告','基于标准数据资产生成结构化分析报告','<h3>报告能力</h3><p>选择国家与指标后，可生成趋势摘要、数据来源说明和治理信息。</p>')}[page]||overview)()}
document.querySelectorAll('.menu').forEach(x=>x.onclick=()=>loadPage(x.dataset.page));loadPage('overview');
</script></body></html>'''
